package com.aftersales.copilot.knowledge.application;
import com.aftersales.copilot.auth.domain.AuthenticatedUser; import com.aftersales.copilot.auth.infrastructure.SnowflakeIdGenerator; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import io.minio.*; import java.security.MessageDigest; import java.time.*; import java.util.*;
@Service public class KnowledgeDocumentService {
 private final JdbcTemplate jdbc; private final SnowflakeIdGenerator ids; private final MinioClient minio; private final String bucket; private final ObjectMapper mapper;
 public KnowledgeDocumentService(JdbcTemplate jdbc,SnowflakeIdGenerator ids,ObjectMapper mapper,@Value("${app.storage.endpoint:http://localhost:9000}") String endpoint,@Value("${app.storage.access-key:minioadmin}") String access,@Value("${app.storage.secret-key:minio_dev_password}") String secret,@Value("${app.storage.bucket:aftersales-private}") String bucket){this.jdbc=jdbc;this.ids=ids;this.mapper=mapper;this.bucket=bucket;this.minio=MinioClient.builder().endpoint(endpoint).credentials(access,secret).build();}
 public Map<String,Object> upload(AuthenticatedUser user,MultipartFile file,String title,String documentType,String scopeType,Long scopeId,String versionLabel){try{if(file.isEmpty()||file.getSize()>20*1024*1024)throw new IllegalArgumentException("DOCUMENT_SIZE_INVALID"); byte[] bytes=file.getBytes(); String sha=hex(MessageDigest.getInstance("SHA-256").digest(bytes)); long baseId=1; long documentId=ids.nextId(); String key="knowledge/"+documentId+"/"+file.getOriginalFilename(); if(!minio.bucketExists(BucketExistsArgs.builder().bucket(bucket).build()))minio.makeBucket(MakeBucketArgs.builder().bucket(bucket).build()); minio.putObject(PutObjectArgs.builder().bucket(bucket).object(key).stream(new java.io.ByteArrayInputStream(bytes),bytes.length,-1).contentType(file.getContentType()).build()); LocalDateTime now=LocalDateTime.now(ZoneOffset.UTC); jdbc.update("INSERT INTO knowledge_base(id,name,code,status,created_at,updated_at) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE updated_at=VALUES(updated_at)",baseId,"Default Knowledge Base","default","ACTIVE",now,now); jdbc.update("INSERT INTO knowledge_document(id,knowledge_base_id,title,document_type,scope_type,scope_id,object_key,file_name,content_type,size_bytes,sha256,version_label,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",documentId,baseId,title,documentType,scopeType,scopeId,key,file.getOriginalFilename(),file.getContentType(),file.getSize(),sha,versionLabel,"UPLOADED",user.id(),now,now); long taskId=ids.nextId(); Map<String,Object> data=Map.of("taskId",taskId,"documentId",documentId,"indexVersion",1,"fileName",file.getOriginalFilename(),"contentType",file.getContentType(),"contentSha256",sha,"objectUrl",minio.getPresignedObjectUrl(GetPresignedObjectUrlArgs.builder().method(io.minio.http.Method.GET).bucket(bucket).object(key).expiry(3600).build()),"metadata",Map.of("documentType",documentType,"scopeType",scopeType,"scopeId",scopeId==null?"":scopeId)); Map<String,Object> envelope=Map.of("eventId",UUID.randomUUID().toString(),"eventType","knowledge.document.index.requested.v1","occurredAt",now.toString(),"traceId",UUID.randomUUID().toString(),"producer","aftersales-server","schemaVersion",1,"data",data); jdbc.update("INSERT INTO ai_task(id,biz_type,biz_id,dedup_key,status,attempt_count,max_attempts,request_snapshot,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)",taskId,"DOCUMENT_INDEX",documentId,"DOCUMENT_INDEX:"+documentId+":1","PENDING",0,3,mapper.writeValueAsString(data),now,now); jdbc.update("INSERT INTO outbox_event(event_id,aggregate_type,aggregate_id,event_type,routing_key,payload,status,retry_count,created_at,updated_at) VALUES(?,?,?,?,?,?,?,0,?,?)",envelope.get("eventId"),"AI_TASK",taskId,envelope.get("eventType"),envelope.get("eventType"),mapper.writeValueAsString(envelope),"NEW",now,now); return Map.of("documentId",documentId,"taskId",taskId,"status","UPLOADED","sha256",sha,"objectKey",key);}catch(Exception e){throw new IllegalStateException(e);}}
 private String hex(byte[] b){var s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x));return s.toString();}
}
